import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int R = readInt(in), C = readInt(in);
        int[] a = new int[R * C];
        for (int i = 0; i < R * C; i++) a[i] = readInt(in);
        int best = 0;
        int[] dr = {-1, -1, 1, 1}, dc = {-1, 1, -1, 1};
        // len2/len0: length of a valid tail starting here with expected value 2/0 that reaches the border; 0 if invalid.
        int[] len2 = new int[R * C], len0 = new int[R * C];
        for (int d = 0; d < 4; d++) {
            // Visit cells so that the next cell in direction d is always computed first.
            int r0 = dr[d] < 0 ? 0 : R - 1, r1 = dr[d] < 0 ? R : -1, rs = dr[d] < 0 ? 1 : -1;
            int c0 = dc[d] < 0 ? 0 : C - 1, c1 = dc[d] < 0 ? C : -1, cs = dc[d] < 0 ? 1 : -1;
            for (int r = r0; r != r1; r += rs)
                for (int c = c0; c != c1; c += cs) {
                    int nr = r + dr[d], nc = c + dc[d];
                    boolean out = nr < 0 || nr >= R || nc < 0 || nc >= C;
                    int i = r * C + c, j = out ? -1 : nr * C + nc;
                    len2[i] = a[i] != 2 ? 0 : out ? 1 : (len0[j] > 0 ? len0[j] + 1 : 0);
                    len0[i] = a[i] != 0 ? 0 : out ? 1 : (len2[j] > 0 ? len2[j] + 1 : 0);
                    if (a[i] == 1) best = Math.max(best, out ? 1 : (len2[j] > 0 ? len2[j] + 1 : 0));
                }
        }
        System.out.println(best);
    }

    static int readInt(DataInputStream in) throws IOException {
        int c = in.read();
        while (c < '0' || c > '9') c = in.read();
        int r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = in.read(); }
        return r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	R, C := next(), next()
	a := make([]int, R*C)
	for i := range a {
		a[i] = next()
	}
	best := 0
	dr, dc := []int{-1, -1, 1, 1}, []int{-1, 1, -1, 1}
	// len2/len0: length of a valid tail starting here with expected value 2/0 that reaches the border; 0 if invalid.
	len2, len0 := make([]int, R*C), make([]int, R*C)
	for d := 0; d < 4; d++ {
		// Visit cells so that the next cell in direction d is always computed first.
		r0, r1, rs := 0, R, 1
		if dr[d] > 0 {
			r0, r1, rs = R-1, -1, -1
		}
		c0, c1, cs := 0, C, 1
		if dc[d] > 0 {
			c0, c1, cs = C-1, -1, -1
		}
		for r := r0; r != r1; r += rs {
			for c := c0; c != c1; c += cs {
				nr, nc := r+dr[d], c+dc[d]
				out := nr < 0 || nr >= R || nc < 0 || nc >= C
				i, j := r*C+c, nr*C+nc
				tail := func(l []int) int { // valid tail continuing from the next cell
					if out {
						return 0
					}
					if l[j] > 0 {
						return l[j]
					}
					return -1
				}
				t0, t2 := tail(len0), tail(len2)
				len2[i], len0[i] = 0, 0
				if a[i] == 2 && t0 >= 0 {
					len2[i] = t0 + 1
				}
				if a[i] == 0 && t2 >= 0 {
					len0[i] = t2 + 1
				}
				if a[i] == 1 && t2 >= 0 {
					best = max(best, t2+1)
				}
			}
		}
	}
	fmt.Println(best)
}
